insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "249", "word": "커터칼퇴", "likes": 0, "saves": 0, "usage": "직장인이 자기 퇴근을 자조적으로 말할 때 쓴다. 남의 퇴근을 두고 쓰면 놀리는 뉘앙스가 된다. 커터칼퇴, 커터칼퇴근 어느 쪽으로 검색해도 이 항목 하나가 나온다.", "origin": "직장인 은어 칼퇴(근)의 칼을 커터칼로 바꾼 말장난. 2026년 1월 언론의 신조어 모음 기사와 SNS 뉴스레터를 타고 퍼졌다. 누가 처음 만들었는지는 확인되지 않았다.", "aliases": ["커터칼퇴근"], "category": "new-slang", "meanings": [{"type": "명사", "examples": [{"de": "Heute keine Meetings, also hab ich den Cutter-Feierabend geschafft.", "es": "Hoy no hubo reuniones, así que logré mi salida a lo cúter.", "ja": "今日は会議が入らなかったからカッターカルトェ成功した。", "vi": "Hôm nay không có họp nên mình chuồn sớm trót lọt.", "eng": "No meetings today, so I pulled off a box-cutter clock-out.", "kor": "오늘 회의 안 잡혀서 커터칼퇴 성공했다."}, {"de": "Hab die ganze Zeit auf den Chef geschielt und dann doch den Cutter-Feierabend gemacht ...", "es": "Estuve pendiente del jefe y al final salí a lo cúter...", "ja": "チーム長の顔色をうかがって結局カッターカルトェ…", "vi": "Cứ liếc sếp mãi rồi cuối cùng cũng chuồn sớm được tí...", "eng": "Kept watching for the boss and ended up doing a box-cutter clock-out...", "kor": "팀장님 눈치 보다가 결국 커터칼퇴..."}], "definition": "정시 퇴근을 뜻하는 칼퇴까지는 못 하지만, 사무실 분위기를 살피며 최대한 빨리 나오는 퇴근. 잘 드는 칼이 아니라 얇고 무딘 커터칼에 빗대어 어중간한 자신을 자조하는 말이다. 원말인 '커터칼퇴근'과 줄인 '커터칼퇴'는 같은 말이며, 언론 기사에서는 주로 '커터칼퇴근'으로 쓴다.", "definition_i18n": {"de": "Kein sauberer Punkt-Feierabend, sondern der früheste Abgang, den die Bürostimmung zulässt. Der Witz liegt im Abstieg vom scharfen Messer zum labbrigen Cuttermesser - ein Seitenhieb auf die eigene halbe Sache. Die Vollform 커터칼퇴근 und die Kurzform 커터칼퇴 bedeuten dasselbe; die Presse nutzt meist die Vollform.", "en": "Not a clean on-time exit, but the earliest escape the office mood allows. The joke is the downgrade from a sharp knife to a flimsy box cutter - a self-deprecating jab at your own half-measure. The full form 커터칼퇴근 and the clipped 커터칼퇴 mean the same thing; press coverage mostly uses the full form.", "es": "No es una salida puntual limpia, sino la huida más temprana que permite el ambiente de la oficina. La gracia está en bajar del cuchillo afilado al cúter endeble: una burla de tu propia media tinta. La forma completa 커터칼퇴근 y la abreviada 커터칼퇴 significan lo mismo; la prensa usa sobre todo la completa.", "ja": "定時退勤を意味するカルトェには届かないが、職場の空気を読みながら可能な限り早く帰ること。よく切れる包丁ではなく薄くて頼りないカッターナイフに例え、中途半端な自分を自嘲する言葉。 元の形「커터칼퇴근」と略した「커터칼퇴」は同じ言葉で、報道では主に元の形が使われる。", "vi": "Không phải kiểu về đúng giờ dứt khoát, mà là chuồn sớm nhất có thể trong mức không khí văn phòng cho phép. Cái hài nằm ở chỗ hạ cấp từ dao sắc xuống dao rọc giấy mỏng manh - tự giễu sự nửa vời của mình. Dạng đầy đủ 커터칼퇴근 và dạng rút gọn 커터칼퇴 là một; báo chí chủ yếu dùng dạng đầy đủ."}}], "created_at": "2026-09-04T10:00:00+00:00", "short_desc": "칼퇴는 못 하고 눈치 보며 조금 일찍 나오는 퇴근", "usage_i18n": {"de": "Büroangestellte nutzen es selbstironisch über den eigenen Feierabend; über andere gesagt klingt es neckend.", "en": "Office workers use it self-deprecatingly about their own exit; aimed at someone else it becomes teasing.", "es": "Los oficinistas lo usan para burlarse de su propia salida; dirigido a otro suena a pulla.", "ja": "会社員が自分の退勤を自嘲的に言うときに使う。他人の退勤に使うとからかう響きになる。", "vi": "Dân văn phòng dùng để tự giễu chuyện về sớm của mình; nói về người khác thì thành trêu chọc."}, "origin_i18n": {"de": "Ein Wortspiel mit kaltoe (Punkt-Feierabend, wörtlich messerscharfer Feierabend), bei dem das Messer zum Cuttermesser wird. Verbreitet ab Januar 2026 über Presse-Rückblicke zu Neologismen und Social-Newsletter. Der Urheber ist unbestätigt.", "en": "A pun on the office-slang kaltoe (an on-time exit, literally a knife-sharp clock-out), swapping the knife for a box cutter. It spread in January 2026 through year-in-slang press round-ups and social newsletters. Who coined it is unverified.", "es": "Un juego de palabras sobre kaltoe (salida puntual, literalmente una salida afilada como un cuchillo), cambiando el cuchillo por un cúter. Se difundió en enero de 2026 vía recopilaciones de prensa y newsletters. Se desconoce quién lo acuñó.", "ja": "会社員の隠語カルトェ(定時退勤、直訳は刃物のように鋭い退勤)の刃をカッターナイフに置き換えた言葉遊び。2026年1月の新造語まとめ記事とSNSニュースレターを通じて広まった。誰が最初に作ったかは未確認。", "vi": "Chơi chữ từ kaltoe (về đúng giờ, nghĩa đen là tan làm sắc như dao), đổi dao thành dao rọc giấy. Lan rộng tháng 1/2026 qua các bài báo tổng hợp từ mới và newsletter mạng xã hội. Chưa rõ ai là người đầu tiên dùng."}, "romanization": "Keo-teo-kal-toe", "translations": [{"lang": "🇺🇸 EN", "text": "Box-cutter clock-out (sneaking out early)"}, {"lang": "🇯🇵 JA", "text": "定時ではないが少し早めの退勤"}, {"lang": "🇨🇳 ZH", "text": "看眼色稍微早点下班"}, {"lang": "🇻🇳 VI", "text": "Chuồn về sớm nhất có thể"}, {"lang": "🇪🇸 ES", "text": "Salida a lo cúter (irse antes con disimulo)"}, {"lang": "🇩🇪 DE", "text": "Cutter-Feierabend (früher rausschleichen)"}], "pronunciation": "[커터칼퇴]", "related_words": ["칼퇴", "워라밸", "좋좋소"], "short_desc_i18n": {"de": "So früh Feierabend machen, wie man sich traut - kein sauberer Punkt-Feierabend", "en": "Leaving work as early as you dare, short of a clean on-time exit", "es": "Salir del trabajo lo antes que te atreves, sin llegar a ser una salida puntual", "ja": "定時退勤とまではいかないが、様子をうかがって少し早めに帰ること", "vi": "Về sớm nhất có thể trong khả năng, chưa đến mức đúng giờ tan làm"}}$json$::jsonb);

update public.words set aliases = '{}' where aliases is null;

